/**
 * Finland Wildlife Vehicle-Collision Camera Deployment Plan (2021–2025)
 *
 * Data sources:
 * 1. Official cervid collision records (2021–2025): Suomen riistakeskus, Liikenne- ja viestintävirasto
 *    Traficom, Väylävirasto & Ramboll Mobility Analytics (https://mobilityanalytics.ramboll.com/onn/hirvielain/)
 * 2. Official municipal boundaries & public road centerlines: Maanmittauslaitos (NLS) & Väylävirasto Digiroad
 *
 * Deployment model:
 * - 100 permanent year-round roadside wildlife cameras per municipality across Finland's Top 5
 *   wildlife collision cities (500 cameras total).
 * - Placed in historically prominent wildlife collision locations across each municipality,
 *   snapped directly to motor-road centerlines and pointed along the road corridor.
 */

export interface SpeciesCollisionBreakdown {
  whiteTailedDeer: number;
  roeDeer: number;
  moose: number;
  fallowDeer: number;
  forestReindeer: number;
}

export type CompactPlannedCameraTuple = [
  unitNumber: number,
  lat: number,
  lng: number,
  bearingDeg: number,
  historicalAccidents: number,
  roadLabel: string,
];

export interface PlannedCameraNode {
  id: string;
  cityId: string;
  cityName: string;
  unitNumber: number;
  rankInCity: number;
  clusterIndex: number;
  clusterSize: number;
  roadLabel: string;
  clusterLabel: string;
  lat: number;
  lng: number;
  bearingDeg: number;
  reverseBearingDeg?: number;
  historicalAccidents: number;
  whiteTailedDeer: number;
  roeDeer: number;
  moose: number;
}

export interface CityCameraPlan {
  id: string;
  code: number;
  rank: number;
  name: string;
  region: string;
  prefix: string;
  primaryRoads: string;
  zoom: number;
  center: { lat: number; lng: number };
  totalAccidents: number;
  coveredAccidents: number;
  landAreaKm2: number;
  speciesTotals: SpeciesCollisionBreakdown;
  byYear: Record<string, number>;
  /** Municipal boundary polylines as [lng, lat][] rings */
  borderLines: Array<Array<[number, number]>>;
  /** Aggregated 2021–2025 collision prevalence cells as [lng, lat, collisionCount] */
  hotspots: Array<[number, number, number]>;
  /** 100 permanent year-round roadside camera placements at historically prominent collision locations */
  cameras: PlannedCameraNode[];
}

export type CameraPriorityTier = 'critical' | 'high' | 'elevated';
export type CityWildlifeCameraPlan = CityCameraPlan;

export const RAMBOLL_DATA_SOURCE_URL = 'https://mobilityanalytics.ramboll.com/onn/hirvielain/';
export const RAMBOLL_DATA_PERIOD = '2021–2025';
export const RAMBOLL_DATASET_YEARS = RAMBOLL_DATA_PERIOD;
export const RAMBOLL_NATIONAL_TOTAL_ACCIDENTS = 67_081;
export const CAMERAS_PER_CITY = 100;
export const PHYSICAL_CAMERAS_TOTAL = 500;

interface RawCityCameraPlan extends Omit<CityCameraPlan, 'cameras'> {
  rawCameras: CompactPlannedCameraTuple[];
}

function allocateSpecies(
  total: number,
  totals: SpeciesCollisionBreakdown
): { whiteTailedDeer: number; roeDeer: number; moose: number } {
  const denom = Math.max(1, totals.whiteTailedDeer + totals.roeDeer + totals.moose);
  const rw = (total * totals.whiteTailedDeer) / denom;
  const rr = (total * totals.roeDeer) / denom;
  const rm = (total * totals.moose) / denom;
  let w = Math.floor(rw);
  let r = Math.floor(rr);
  let m = Math.floor(rm);
  const rem = total - (w + r + m);
  const order: Array<'w' | 'r' | 'm'> = (
    [
      ['w', rw - w],
      ['r', rr - r],
      ['m', rm - m],
    ] as Array<['w' | 'r' | 'm', number]>
  )
    .sort((a, b) => b[1] - a[1])
    .map((x) => x[0]);
  for (let i = 0; i < rem; i++) {
    const k = order[i % 3];
    if (k === 'w') w++;
    else if (k === 'r') r++;
    else m++;
  }
  return { whiteTailedDeer: w, roeDeer: r, moose: m };
}

