export const TOP_5_WILDLIFE_ACCIDENT_CITIES: CityCameraPlan[] = RAW_CITY_PLANS.map((rawCity) => {
  const cameras: PlannedCameraNode[] = rawCity.rawCameras.map(
    ([unitNumber, lat, lng, bearingDeg, historicalAccidents, roadLabel], idx) => {
      const rankInCity = idx + 1;
      const sp = allocateSpecies(historicalAccidents, rawCity.speciesTotals);
      return {
        id: `${rawCity.prefix}-${String(unitNumber).padStart(3, '0')}`,
        cityId: rawCity.id,
        cityName: rawCity.name,
        unitNumber,
        rankInCity,
        clusterIndex: rankInCity,
        clusterSize: 1,
        roadLabel,
        clusterLabel: `Hotspot #${rankInCity} · ${roadLabel}`,
        lat,
        lng,
        bearingDeg,
        historicalAccidents,
        whiteTailedDeer: sp.whiteTailedDeer,
        roeDeer: sp.roeDeer,
        moose: sp.moose,
      };
    }
  );

  const { rawCameras: _unused, ...rest } = rawCity;
  void _unused;
  return {
    ...rest,
    cameras,
  };
});

export const ALL_PLANNED_CAMERAS: PlannedCameraNode[] = TOP_5_WILDLIFE_ACCIDENT_CITIES.flatMap(
  (city) => city.cameras
);

export const TOTAL_TOP5_ACCIDENTS = TOP_5_WILDLIFE_ACCIDENT_CITIES.reduce(
  (sum, city) => sum + city.totalAccidents,
  0
);

export const TOTAL_COVERED_ACCIDENTS = TOP_5_WILDLIFE_ACCIDENT_CITIES.reduce(
  (sum, city) => sum + city.coveredAccidents,
  0
);
